"""Write decision/run metadata from closed pilot evidence; never invokes a model."""
import hashlib,json,re
from datetime import datetime,timezone
from pathlib import Path
from .evaluate import load_jsonl
from .source_validation import verify_source_revision

ROOT=Path('results/v2');CANDIDATES=['luna-vault-direct','qdrant-native','basic-memory']
def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    f=read(ROOT/'frozen-evaluation.json');g=load_jsonl('fixtures/v2/gold-after-submission.jsonl')
    if [x['id'] for x in g]!=f['question_ids']:raise ValueError('gold IDs/order differs')
    for x in g:
        for source in x['required_sources']:verify_source_revision('fixtures/v2/vault',x['organization_id'],x['knowledge_space_id'],source['document_id'],source['revision'])
        for choices in x['answer_patterns']:
            for pattern in choices:re.compile(pattern)
    integration=read(ROOT/'integration-summary.json');integration['suites']['native-assignment-repair']={'passed':1,'skipped':0,'evidence':'results/v2/harness/native-assignment-repair-test.log','scope':'post-pilot repair; no additional model session'};integration['passed']=sum(s['passed'] for s in integration['suites'].values());(ROOT/'integration-summary.json').write_text(json.dumps(integration,indent=2)+'\n')
    r={c:read(ROOT/c/'retrieval/quality-summary.json') for c in CANDIDATES};e={c:read(ROOT/c/'answers/evaluation.json') for c in CANDIDATES};t={c:read(ROOT/c/'retrieval/retrieval-summary.json') for c in CANDIDATES}
    lines=['','## Category detail','', '| R category | Markdown recall | Qdrant recall | Basic Memory recall |','|---|---:|---:|---:|']
    for category in ['semantic_paraphrase','multihop','temporal','revision']:
        values=[]
        for c in CANDIDATES:
            scores=[s['recall_at_5'] for s in r[c]['scores'] if s['category']==category];values.append(f'{100*sum(scores)/len(scores):.1f}%')
        lines.append('| '+category+' | '+' | '.join(values)+' |')
    lines += ['', 'All three R engines returned nonempty results for all eight negatives. This is a retrieval calibration limitation; every returned source stayed inside the trusted principal. Eligible E obsolete citation count is zero for all three engines.','', '| E common verified 10 | Component/citation passes | Mean wrapper operations | Mean response body bytes |','|---|---:|---:|---:|']
    for c in CANDIDATES:lines.append(f"| {c} | {e[c]['paired_strict_grounded_rate']*100:.1f}% | {e[c]['paired_wrapper_calls_mean']:.2f} | {e[c]['paired_response_bytes_mean']:.1f} |")
    lines+=['','These ten questions cover temporal decisions, revisions and negatives. The raw wrapper count is higher for both indexed candidates on this audited subset; protocol failures and unequal correctness prevent validated savings claims. Native token/call savings remain null.','']
    with (ROOT/'COMPARISON.md').open('a') as out:out.write('\n'.join(lines))
    adr=f'''# ADR-0002 — semantic memory pilot

Status: pilot decision recorded; production adoption deferred for review.

BENCH-0002 executed a frozen 80-note FR/EN corpus across ten org/project scopes. Five native Luna implementation streams built isolated V2 code. Qdrant used a reproducible, genuinely learned local 384D bilingual encoder and sparse RRF; Basic Memory ran real stdio MCP through a custom façade; Cognee's canonical offline tokenizer and actual native add/dataset persistence were repaired. Graphiti's shared encoder runs, but genuine graph extraction and Cognee cognify remain blocked without a provisioned capable local extraction LLM.

The 40-question R pilot measured macro source recall@5 of **96.9% Basic Memory**, **84.4% direct Markdown** and **73.4% Qdrant hybrid**, over 32 answerable questions. Median adapter latency was **1778.798 ms**, **1.525 ms**, and **1.574 ms**, respectively. Basic Memory's path starts MCP and synchronizes/indexes a private copy on every search. This cost is implementation-specific. Qdrant's current-only filter returned zero obsolete hits but prevents historical source recall. Direct returned 23 obsolete hits and Basic Memory eight; historical questions are exempt when their old source is required. No cross-scope result was observed in the 120 R result sets. All eight negative retrieval questions returned hits for every engine.

This run does not demonstrate a semantic retrieval advantage. The small neural model has 323 word tokens and 40 authored translation pairs; it is not representative of a pretrained multilingual sentence model. The official pretrained distribution was denied by the managed proxy. Dense-only and fusion/obsolete-filter ablations were not run. R Pareto points are direct Markdown and Basic Memory; Qdrant is dominated on measured recall/median latency in this tiny pilot. These findings do not select a universal engine.

The E lane made at most 20 native answer attempts per runnable engine: 59 final submissions and one unrecovered direct attempt. Prompt provenance is verified for only 38 submissions (12 direct, 13 Qdrant, 13 Basic). Eighteen prompts were not captured; three captured prompts had wrong question/scope assignments. Those are unscored, not fabricated measurements. On the ten common verified/unassisted questions, component/citation scores are 90% direct, 90% Qdrant and 100% Basic, with mean wrapper counts 3.4, 4.1 and 4.5. This subset covers temporal/revision/negative questions only. Full-20 E quality is **null/INCOMPLETE**. Schema/cwd/capability failures, one extra hint, an early corrected response mapping, unrestricted native tools and language deviations make the E comparison exploratory.

Native input/cached/output/reasoning tokens, native tool counters, immutable served snapshots and subscription spend were not exposed. They remain null. Wrapper calls, payload bytes and local encoder input units are separate observations and do not establish native token savings. Ingest factories and own/child CPU/I/O are captured; RAM is process high-water RSS, physical cache is uncontrolled, Basic Memory child peak RAM and model-training resources are unavailable. Amortization is arithmetic over measured factories, not execution at 200/2k/20k queries.

Decision: retain scoped Markdown as the reference and defer production memory selection. Keep the verified Basic Memory MCP and Cognee tokenizer/add repairs. Retain Qdrant's real neural implementation as a research candidate, with the model's limited training explicitly disclosed. Do not describe blocked Graphiti/Cognee graph paths as exercised or recommend graph adoption from this evidence. No validated native token/call savings are claimed.

The deterministic native_prompt.py preparation repair now checks question/session IDs, principal and capability, uses an absolute client path and includes exact JSON schema. Its integration test passed after this pilot; the repaired protocol was not used for additional sessions. A further pilot should provision approved pinned pretrained embeddings and a capable local extraction LLM, validate the entire native dispatch path before freezing, capture authoritative prompts/finals atomically, and use a withheld dataset with an actual access boundary. Review this pilot before any rerun, full benchmark or load test.

Reproducibility: results/v2/run-manifest.json, COMPARISON.md, prompt-audit.json, raw R/E traces, dependency locks, model hashes/training recipe, artifact-sha256.json and validation.json. {integration['passed']} V2 integration checks passed; one Graphiti integration class was skipped. Nine restored offline tests also passed. All 189 V1 tracked files are byte-identical to commit 94a2a4beacf90f6a9640ecd43ebae8b8c9e7a708. The V2 branch originally deleted those files; they are restored unchanged.

The pilot has stopped. No full benchmark, load test, nested authenticated Codex CLI, external paid inference or network-policy bypass was executed.
'''
    Path('ADR-0002-semantic-memory.md').write_text(adr)
    post={str(p):sha(p) for p in sorted(Path('benchkit/v2').glob('*')) if p.is_file()}
    m={'benchmark':'BENCH-0002','status':'PILOT_STOPPED_R_COMPLETE_E_CONTROLLED_COMPARISON_INCOMPLETE','branch':'codex/bench-0002-semantic-pilot','target_branch':'codex/bench-0001-real-pilot','starting_commit':'59df43df69b9347bed7c0ea6c2711bbf39136c3f','v1_reference_commit':'94a2a4beacf90f6a9640ecd43ebae8b8c9e7a708','finished_at_utc':datetime.now(timezone.utc).isoformat(),'seed':20261018,'blindness':f['blindness'],'freeze_manifests':['results/v2/frozen-implementations.json','results/v2/frozen-evaluation.json','results/v2/frozen-postprocessing.json'],'source_hashes':f['source_sha256'],'postprocessing_and_postpilot_repair_sha256':post,'model':read(ROOT/'models/manifest.json'),'corpus_sha256':f['corpus_sha256'],'questions_sha256':f['questions_sha256'],'gold_sha256':sha('fixtures/v2/gold-after-submission.jsonl'),'gold_release':read('fixtures/v2/gold-manifest.json'),'policy':f['policy'],'implementation_delegation':read(ROOT/'implementation-delegation.json'),'native_answer_dispatch':'results/v2/harness/native-E-dispatch.json','native_answer_attempts':{'luna-vault-direct':20,'qdrant-native':20,'basic-memory':20},'native_answer_finals':{c:e[c]['submitted_answers'] for c in CANDIDATES},'quality_eligible_verified_prompts':{c:e[c]['scorable_answers'] for c in CANDIDATES},'common_verified_unassisted_questions':read(ROOT/'harness/prompt-audit.json')['common_unassisted_question_ids'],'native_tokens':{'input':None,'cached':None,'output':None,'reasoning':None},'native_tool_calls':None,'native_served_snapshots':None,'native_token_or_call_savings':None,'candidate_results':{c:{'R_status':t[c]['status'],'R_questions':40,'R_recall_at_5':r[c]['recall_at_5'],'R_backend_latency_ms':t[c]['backend_search_latency_ms'],'E_status':e[c]['full_set_quality_status'],'E_quality_full20':None,'E_eligible_component_citation_passes':e[c]['strict_grounded_correct'],'E_wrapper_calls_observed':e[c]['wrapper_calls_total']} for c in CANDIDATES},'stage_blocked':{'cognee':{'stage':'cognify graph/vector extraction/indexing','actual_add_verified':True,'evidence':'results/v2/cognee/evidence.json','quality':None},'graphiti':{'stage':'native extraction and temporal retrieval','local_encoder_verified':True,'evidence':'results/v2/graphiti/model-blocker.json','quality':None}},'tests':integration,'validation':'results/v2/validation.json','artifact_hash_index':'results/v2/artifact-sha256.json','scope_limits':{'R_questions_per_runnable_candidate':40,'E_attempts_per_runnable_candidate_max':20,'full_benchmark':False,'load_tests':False,'additional_E_after_prompt_repair':False,'nested_authenticated_cli':False,'external_paid_inference':False,'network_policy_bypass':False},'reproduction_commands':['python3 -m benchkit.v2.development_corpus','bash scripts/v2-retrieval-pilot.sh','python3 -m benchkit.v2.audit_prompts  # requires original private capability configs; exported audit remains immutable evidence','python3 -m benchkit.v2.summarize_answers --candidate <name> --gold fixtures/v2/gold-after-submission.jsonl','XDG_CACHE_HOME=/tmp/bench-v2-font-cache python3 -m benchkit.v2.report','python3 -m benchkit.v2.validate_run','python3 -m benchkit.v2.finalize']}
    m.update({'prompt_audit':'results/v2/harness/prompt-audit.json','telemetry_coverage':'results/v2/telemetry-coverage.json','local_usage_ledger':'results/v2/usage-ledger.json','method_amendments':'results/v2/method-amendments.json'})
    (ROOT/'run-manifest.json').write_text(json.dumps(m,indent=2)+'\n')
    files=sorted(p for root in (Path('results/v2'),Path('fixtures/v2'),Path('benchkit/v2')) for p in root.rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.name!='artifact-sha256.json')+[Path('ADR-0002-semantic-memory.md')]
    (ROOT/'artifact-sha256.json').write_text(json.dumps({'sha256':{str(p):sha(p) for p in files}},indent=2)+'\n')
    print(json.dumps({'R_recall':{c:r[c]['recall_at_5'] for c in CANDIDATES},'E_verified':{c:e[c]['scorable_answers'] for c in CANDIDATES},'integration_passed':integration['passed'],'hashed_artifacts':len(files)}))
if __name__=='__main__':main()
